from topics_a import t, T
P='physio'
t('physiotherapist',P,'a physiotherapist',"Physiotherapists assess movement and pain, then use exercise, manual therapy and advice to help you recover from injury, surgery or long-term conditions.",["Exercise is central to most plans.","Ask how progress will be measured.","Check HCPC registration."])
t('physio',P,'a physio',"\"Physio\" is short for physiotherapy or physiotherapist: assessment and treatment of muscles, joints and movement to reduce pain and restore function.",["Bring comfortable clothing.","First sessions include assessment.","Expect home exercises."])
t('physiotherapy',P,'physiotherapy',"Physiotherapy treats pain and movement problems through assessment, exercise, hands-on treatment and education.",["Active treatment works best.","Combine clinic and home work.","Review progress regularly."])
t('physiotherapy-clinic',P,'a physiotherapy clinic',"Physiotherapy clinics offer assessment rooms, gym equipment and often specialist physiotherapists for sport, spine or neurology.",["Ask about specialist interests.","Gym access helps rehab.","Check insurer recognition."])
t('private-physiotherapist',P,'a private physiotherapist',"Private physiotherapists offer faster access and flexible appointments, self-pay or through health insurance.",["You can usually self-refer.","Insurers may cap sessions.","Ask about clinic hours."])
t('musculoskeletal-physiotherapist',P,'a musculoskeletal physiotherapist',"MSK physiotherapists treat problems with muscles, joints, tendons and ligaments, from back pain to sports injuries.",["MSK is the most common physio specialty.","Diagnosis guides treatment.","Load management is key."])
t('rehabilitation-physiotherapist',P,'a rehabilitation physiotherapist',"Rehabilitation physiotherapists rebuild strength, mobility and confidence after injury, illness or surgery.",["Goals should be specific.","Progress is gradual.","Return-to-activity plans help."])
t('post-operative-physiotherapy',P,'post-operative physiotherapy',"Post-operative physiotherapy follows your surgeon's protocol to restore movement and strength after operations such as joint replacements or ligament repairs.",["Bring the surgeon's protocol.","Start when your surgeon advises.","Swelling management matters."])
t('acl-rehab-physiotherapy',P,'ACL rehab physiotherapy',"ACL rehabilitation restores knee movement, strength and control after anterior cruciate ligament injury or reconstruction, often over many months.",["Return to sport usually takes many months.","Strength testing guides progression.","Some ACL injuries are managed without surgery."])
t('back-pain-physiotherapy',P,'back pain physiotherapy',"Back pain physiotherapy combines assessment, reassurance, exercise and manual therapy to reduce pain and get you moving.",["Most back pain improves with time and activity.","Red-flag symptoms need urgent care.","Strength and movement help recovery."])
t('back-pain-physiotherapist',P,'a back pain physiotherapist',"Physiotherapists with an interest in spinal pain assess the cause of back pain and build tailored exercise plans.",["Imaging is often not needed.","Stay active where possible.","Workplace changes help."])
t('back-pain-treatment',P,'back pain treatment',"Back pain treatment options include physiotherapy, osteopathy, chiropractic care, exercise and, for some, specialist medical review.",["Choose a registered practitioner.","Persistent pain may need GP review.","Combine treatment with exercise."])
t('neck-pain-physiotherapy',P,'neck pain physiotherapy',"Neck pain physiotherapy addresses stiffness, posture-related pain and headaches with exercise and manual techniques.",["Desk set-up matters.","Gentle movement helps.","Numbness or weakness needs assessment."])
t('knee-pain-physiotherapy',P,'knee pain physiotherapy',"Knee pain physiotherapy treats problems such as patellofemoral pain, ligament strains and arthritis with targeted strengthening.",["Hip strength affects knees.","Load changes help pain.","Swelling after injury should be assessed."])
t('knee-physiotherapist',P,'a knee physiotherapist',"Knee physiotherapists specialise in knee injuries, arthritis and rehabilitation after knee surgery.",["Ask about sports experience.","Strength testing guides progress.","Bring scan reports."])
t('hip-pain-physiotherapy',P,'hip pain physiotherapy',"Hip pain physiotherapy treats tendon problems, arthritis and groin pain with exercise and activity advice.",["Lateral hip pain often responds to loading.","Sleep position matters.","Arthritis benefits from exercise."])
t('frozen-shoulder-physiotherapy',P,'frozen shoulder physiotherapy',"Frozen shoulder physiotherapy helps manage pain and stiffness through its phases and gradually restores movement.",["Frozen shoulder can last many months.","Injections may help some people.","Gentle exercise maintains movement."])
t('carpal-tunnel-physiotherapy',P,'carpal tunnel physiotherapy',"Physiotherapy for carpal tunnel syndrome uses splinting, nerve gliding and activity changes, with referral if symptoms persist.",["Night splints are commonly used.","Persistent numbness needs review.","Workstation changes help."])
t('plantar-fasciitis-physiotherapy',P,'plantar fasciitis physiotherapy',"Plantar fasciitis physiotherapy reduces heel pain with stretching, strengthening, footwear advice and load management.",["Morning heel pain is typical.","Calf strength matters.","Footwear and insoles may help."])
t('neurological-physiotherapist',P,'a neurological physiotherapist',"Neurological physiotherapists help people with stroke, MS, Parkinson's, brain or spinal injury improve movement, balance and independence.",["Goals focus on daily function.","Home visits are common.","Family involvement helps."])
t('paediatric-physiotherapist',P,'a paediatric physiotherapist',"Paediatric physiotherapists work with babies and children on development, movement, sports injuries and long-term conditions.",["Play-based therapy is common.","Parents learn exercises.","Ask about experience with your child's condition."])
t('home-visit-physiotherapist',P,'a home visit physiotherapist',"Home visit physiotherapists treat people who find travel difficult, such as after surgery, a stroke or with frailty.",["Home rehab uses real-life tasks.","Falls prevention is a common focus.","Ask about visiting area."])
t('osteopath','osteopath','an osteopath',"Osteopaths use hands-on treatment, exercise and advice to help with back pain, neck pain, joint problems and muscle tension.",["Check GOsC registration.","Expect a full case history.","Ask about home exercises."])
t('chiropractor','chiro','a chiropractor',"Chiropractors assess and treat problems with the spine, joints and muscles, often using spinal manipulation alongside exercise.",["Check GCC registration.","Ask about evidence for your problem.","Avoid long prepaid treatment plans."])
t('podiatrist','podiatrist','a podiatrist',"Podiatrists treat foot and lower-limb problems, from nail and skin conditions to heel pain, gait problems and diabetic foot care.",["Check HCPC registration.","Bring your usual footwear.","People with diabetes need regular foot checks."])
O='optician'
t('optician',O,'an optician',"Opticians test eyes, check eye health, and supply glasses and contact lenses; the eye examination itself is carried out by an optometrist.",["Regular tests check eye health as well as vision.","Get a copy of your prescription.","Ask about OCT scans."])
t('optometrist',O,'an optometrist',"Optometrists examine eyes, detect conditions such as glaucoma and cataracts, prescribe lenses and, with extra qualifications, treat some conditions.",["Some optometrists can prescribe medicines.","Report sudden changes promptly.","Children benefit from early tests."])
t('eye-test',O,'an eye test',"An eye test checks your vision and the health of your eyes, often including pressure checks and imaging of the back of the eye.",["Many people qualify for free NHS tests.","Bring current glasses.","Tell the optometrist about symptoms."])
t('emergency-eye-care',O,'emergency eye care',"Urgent eye care services assess red eyes, sudden vision changes, flashes, floaters and eye injuries quickly.",["Many areas have urgent optometry services.","Chemical injuries need immediate rinsing and A&E.","Sudden vision loss needs same-day care."])
t('audiologist','audiologist','an audiologist',"Audiologists assess hearing, fit and adjust hearing aids, help with tinnitus and provide wax removal and hearing protection.",["Check HCPC registration.","Ask about trial periods.","Aftercare is as important as the device."])
t('hearing-test','audiologist','a hearing test',"A hearing test measures how well you hear different pitches and volumes, and checks the ear canal and eardrum.",["Tests are painless.","Results are shown on an audiogram.","Sudden loss needs urgent care."])
C='counsellor'
t('counsellor',C,'a counsellor',"Counsellors provide a confidential space to talk through difficulties, understand feelings and find ways forward.",["Fit with your counsellor matters.","Check accredited registers.","Ask about their approach."])
t('private-counsellor',C,'a private counsellor',"Private counsellors offer faster access, choice of approach and flexible times, including evenings and online sessions.",["Introductory calls help you choose.","Ask about fees and cancellation.","Check registration."])
t('private-therapist',C,'a private therapist',"Private therapists, including psychotherapists and psychologists, offer talking therapies for a wide range of problems.",["Titles vary; check registers.","Approaches include CBT, psychodynamic and humanistic.","Ask about session length."])
t('anxiety-counselling',C,'anxiety counselling',"Anxiety counselling helps you understand worry and panic, learn coping strategies and reduce avoidance.",["CBT is well supported for anxiety.","Physical symptoms are common.","Small steps build confidence."])
t('anxiety-therapist',C,'an anxiety therapist',"Anxiety therapists use approaches such as CBT and exposure work for generalised anxiety, panic, social anxiety and phobias.",["Ask about experience with your type of anxiety.","Homework between sessions helps.","Review progress regularly."])
t('depression-counselling',C,'depression counselling',"Depression counselling offers support for low mood, loss of interest and hopelessness, often alongside GP care.",["Talk to your GP about medication options.","Behavioural activation can help.","Seek urgent help if you feel unsafe."])
t('depression-counsellor',C,'a depression counsellor',"Counsellors experienced with depression offer a steady, supportive relationship and structured approaches to lift mood.",["Regular sessions help.","Combine with lifestyle support.","Tell your counsellor if things get worse."])
t('bereavement-counselling',C,'bereavement counselling',"Bereavement counselling helps people cope with grief after the death of someone close, at whatever pace they need.",["Grief has no fixed timetable.","Charities also offer support.","Anniversaries can be hard."])
t('bereavement-counsellor',C,'a bereavement counsellor',"Bereavement counsellors specialise in grief and loss, including sudden, traumatic or complicated bereavement.",["Specialist training helps with traumatic loss.","Children may need separate support.","Talking can ease isolation."])
t('couples-counselling',C,'couples counselling',"Couples counselling helps partners improve communication, rebuild trust and decide their future together.",["Both partners usually attend.","Counsellors stay neutral.","Separation counselling is also available."])
t('couples-counsellor',C,'a couples counsellor',"Couples counsellors are trained in relationship therapy and work with couples on conflict, intimacy and change.",["Look for relationship-specific training.","Ask about online sessions.","Discuss goals together."])
t('child-counselling',C,'counselling for a child',"Child counsellors use play, art and talk to help children and young people with anxiety, behaviour, family change and loss.",["Check child-specific training and safeguarding.","Parents are involved appropriately.","Schools may offer support."])
t('addiction-counselling',C,'addiction counselling',"Addiction counselling supports people with alcohol, drug, gambling or other addictions to understand patterns and build recovery.",["Medical detox may be needed for alcohol.","Groups such as AA complement therapy.","Family support helps."])
t('addiction-counsellor',C,'an addiction counsellor',"Addiction counsellors have specialist training in substance misuse and behavioural addictions.",["Ask about relapse prevention.","Check FDAP or other accreditation.","Plan aftercare."])
t('alcohol-counselling',C,'alcohol counselling',"Alcohol counselling helps people cut down or stop drinking, address underlying causes and prevent relapse.",["Stopping suddenly can be dangerous for heavy drinkers; seek medical advice.","Set clear goals.","Local services may be free."])
t('anger-management-counselling',C,'anger management counselling',"Anger management counselling helps you understand triggers and develop healthier responses.",["Recognising early signs helps.","Courses and one-to-one options exist.","Partners may be involved."])
t('burnout-counselling',C,'burnout counselling',"Burnout counselling supports people exhausted by chronic work or caring stress to recover and set boundaries.",["Talk to your GP about time off.","Employers may offer support.","Recovery takes time."])
t('eating-disorder-counselling',C,'eating disorder counselling',"Eating disorder counselling provides specialist support for anorexia, bulimia, binge eating and related difficulties, alongside medical monitoring.",["Medical monitoring is essential.","Specialist services follow NICE guidance.","Beat offers support and information."])
t('adhd-counselling',C,'ADHD counselling and coaching',"ADHD counselling and coaching help with organisation, emotions and the impact of ADHD on work and relationships, before or after diagnosis.",["Coaching is not a diagnosis.","Strategies help daily life.","Medication is a separate medical decision."])
t('autism-counselling',C,'counselling for autistic people',"Counsellors experienced with autism adapt sessions to communication and sensory needs, supporting wellbeing and identity.",["Ask about neurodiversity-affirming practice.","Session format can be adapted.","Diagnosis is not required."])
t('cbt-therapist',C,'a CBT therapist',"CBT therapists use cognitive behavioural therapy to change unhelpful thoughts and behaviours, especially for anxiety and depression.",["BABCP accreditation shows CBT training.","Sessions are structured.","Homework is part of CBT."])
t('cognitive-behavioural-therapist',C,'a cognitive behavioural therapist',"Cognitive behavioural therapists deliver evidence-based CBT for anxiety, depression, OCD, PTSD and more.",["Courses are often time-limited.","Ask about outcome measures.","Check BABCP accreditation."])
t('emdr-therapist',C,'an EMDR therapist',"EMDR therapists use eye movement desensitisation and reprocessing to treat trauma and PTSD.",["NICE recommends EMDR for PTSD.","Check EMDR Association UK accreditation.","Preparation sessions come first."])
t('adhd-assessment','assessment','an ADHD assessment',"An ADHD assessment involves a detailed history, questionnaires and often input from someone who knew you as a child, carried out by a psychiatrist or specialist clinician.",["Ask about shared care before booking.","Right to Choose may apply in England.","Assessments follow NICE guidance."])
t('autism-assessment','assessment','an autism assessment',"An autism assessment uses developmental history and structured observation, often by a multidisciplinary team, to consider an autism diagnosis.",["Assessments for children and adults differ.","Reports support adjustments.","Post-diagnosis support helps."])
